files=[source,master,p/f'{name}-target.png',p/f'{name}-reference.png',p/f'{name}-prompt.txt',Path(__file__)]
(p/f'{name}-inputs.json').write_text(json.dumps({'preCallSha256':{f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in files},'crop':crop,'admissionRegion':[88,116,151,161],'baseFile':source.name,'scope':'Actual master-case geometry/connected grips pilot. Original upper head/legs remain unchanged; material/hip seam and tool occlusion require visual review.'},indent=2)+'\n',encoding='utf-8')
